const gateway = 'http://localhost:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';
const otherApiKey = 'pf_local_dev_bluebird_924bd90d2201';

async function api(path, method = 'GET', body, expected, headers = {}, key = apiKey) {
  const init = { method, headers: { authorization: `Bearer ${key}`, ...headers } };
  if (body !== undefined) { init.headers['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const response = await fetch(`${gateway}${path}`, init);
  let payload;
  try { payload = await response.json(); } catch { payload = null; }
  if (expected !== undefined && response.status !== expected) {
    throw new Error(`${method} ${path}: expected ${expected}, got ${response.status}: ${JSON.stringify(payload)}`);
  }
  return { status: response.status, body: payload };
}

const suffix = Date.now();
const customer = await api('/v1/customers', 'POST', {
  externalReference: `erasure-check-${suffix}`, email: `erasure-check-${suffix}@example.test`,
  name: 'Erasure Check Customer', phone: '+1-555-0199', metadata: { source: 'erasure-check' },
}, 201);
console.log('customer created', customer.body.id);

await api(`/v1/customers/${customer.body.id}/addresses`, 'POST', {
  kind: 'billing', line1: '1 Test St', city: 'Testville', postalCode: '00000', country: 'US',
}, 201);
await api(`/v1/customers/${customer.body.id}/contacts`, 'POST', {
  kind: 'email', value: customer.body.email, isPrimary: true,
}, 201);
const method = await api(`/v1/customers/${customer.body.id}/payment-methods`, 'POST', {
  providerToken: `tok_erasure_check_${suffix}`, type: 'card', brand: 'visa', last4: '4242', billingName: 'Erasure Check Customer',
}, 201);
await api(`/v1/customers/${customer.body.id}/support-tickets`, 'POST', {
  subject: 'Need help with my account', body: `Please reach me at ${customer.body.email}`,
}, 201);

const idempotencyKey = `pay-${suffix}`;
const payment = await api('/v1/payments', 'POST', {
  customerId: customer.body.id, paymentMethodId: method.body.id, amount: 1500, currency: 'USD', description: 'Erasure check payment',
}, 202, { 'idempotency-key': idempotencyKey });
console.log('payment created', payment.body.id, payment.body.status);

for (let i = 0; i < 60; i++) {
  const check = await api(`/v1/payments/${payment.body.id}`);
  if (check.body.status === 'succeeded') { console.log('payment succeeded'); break; }
  await new Promise((r) => setTimeout(r, 250));
}

await new Promise((r) => setTimeout(r, 1000));

const invoice = await api('/v1/invoices', 'POST', {
  customerId: customer.body.id, currency: 'USD', tax: 100,
  lines: [{ description: 'Test invoice', quantity: 1, unitAmount: 900 }],
}, 201);
console.log('invoice created', invoice.body.id, invoice.body.objectKey);

// --- erasure request tests ---
const key1 = `erase-key-1-${suffix}`;
const req1 = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 202, { 'idempotency-key': key1 });
console.log('erasure request created', JSON.stringify(req1.body));

// replay with the SAME key -> same request
const req1replay = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 202, { 'idempotency-key': key1 });
if (req1replay.body.id !== req1.body.id) throw new Error('replay with same key created a different request');
console.log('replay with same key OK');

// different key, SAME customer -> should return existing request (no new workflow)
const key2 = `erase-key-2-${suffix}`;
const req2 = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 202, { 'idempotency-key': key2 });
if (req2.body.id !== req1.body.id) throw new Error('different key for same customer created a duplicate request');
console.log('different key, same customer returns same request OK');

// SAME key, DIFFERENT customer -> 409
const otherCustomer = await api('/v1/customers', 'POST', {
  externalReference: `erasure-check-other-${suffix}`, email: `erasure-check-other-${suffix}@example.test`,
  name: 'Other Customer',
}, 201);
const conflict = await api(`/v1/customers/${otherCustomer.body.id}/erasure-requests`, 'POST', undefined, 409, { 'idempotency-key': key1 });
console.log('same key different customer -> 409 OK', JSON.stringify(conflict.body));

// missing customer -> 404
const fakeId = '00000000-0000-4000-8000-000000000000';
const missing = await api(`/v1/customers/${fakeId}/erasure-requests`, 'POST', undefined, 404, { 'idempotency-key': `missing-${suffix}` });
console.log('missing customer -> 404 OK', JSON.stringify(missing.body));

// cross-tenant customer -> 404 (using other merchant's key against our customer)
const crossTenant = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 404, { 'idempotency-key': `cross-${suffix}` }, otherApiKey);
console.log('cross-tenant -> 404 OK', JSON.stringify(crossTenant.body));

// wait for completion
let finalStatus;
for (let i = 0; i < 60; i++) {
  const status = await api(`/v1/erasure-requests/${req1.body.id}`);
  finalStatus = status.body;
  if (status.body.status === 'completed' || status.body.status === 'failed') break;
  await new Promise((r) => setTimeout(r, 500));
}
console.log('final erasure status', JSON.stringify(finalStatus));
if (finalStatus.status !== 'completed') throw new Error(`erasure did not complete: ${JSON.stringify(finalStatus)}`);

// erasure-requests GET for cross tenant -> 404
const crossGet = await api(`/v1/erasure-requests/${req1.body.id}`, 'GET', undefined, 404, {}, otherApiKey);
console.log('cross-tenant GET -> 404 OK', JSON.stringify(crossGet.body));

// verify customer record scrubbed
const scrubbed = await api(`/v1/customers/${customer.body.id}`);
console.log('scrubbed customer', JSON.stringify(scrubbed.body));
if (scrubbed.body.email === customer.body.email) throw new Error('customer email was not scrubbed');
if (scrubbed.body.status !== 'erased') throw new Error('customer status was not set to erased');

// verify payment method deleted
const pm = await api(`/v1/customers/${customer.body.id}/payment-methods/${method.body.id}`, 'GET', undefined, 404);
console.log('payment method deleted OK', JSON.stringify(pm.body));

// verify payment still exists but snapshot redacted
const paymentAfter = await api(`/v1/payments/${payment.body.id}`);
console.log('payment after erasure', JSON.stringify(paymentAfter.body.customer_snapshot));
if (paymentAfter.body.customer_snapshot.email === customer.body.email) throw new Error('payment customer_snapshot was not redacted');
if (paymentAfter.body.status !== 'succeeded') throw new Error('payment status changed unexpectedly');
if (Number(paymentAfter.body.amount) !== 1500) throw new Error('payment amount was altered');

console.log('ALL CHECKS PASSED');
EOF
