const gateway = 'http://localhost:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';

async function api(path, method = 'GET', body, expected, headers = {}) {
  const init = { method, headers: { authorization: `Bearer ${apiKey}`, ...headers } };
  if (body !== undefined) { init.headers['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const response = await fetch(`${gateway}${path}`, init);
  let payload;
  try { payload = await response.json(); } catch { payload = null; }
  if (expected !== undefined && response.status !== expected) {
    throw new Error(`${method} ${path}: expected ${expected}, got ${response.status}: ${JSON.stringify(payload)}`);
  }
  return { status: response.status, body: payload };
}

// short idempotency key -> 400
const suffix = Date.now();
const customer = await api('/v1/customers', 'POST', {
  externalReference: `edge-${suffix}`, email: `edge-${suffix}@example.test`, name: 'Edge Case Customer',
}, 201);

const short = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 400, { 'idempotency-key': 'short' });
console.log('short idempotency key -> 400 OK', JSON.stringify(short.body));

// missing idempotency key -> 400
const missingKey = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 400, {});
console.log('missing idempotency key -> 400 OK', JSON.stringify(missingKey.body));

// no auth -> 401
const noAuthResponse = await fetch(`${gateway}/v1/customers/${customer.body.id}/erasure-requests`, {
  method: 'POST', headers: { 'idempotency-key': `noauth-${suffix}` },
});
console.log('no auth -> ', noAuthResponse.status);
if (noAuthResponse.status !== 401) throw new Error('expected 401 without auth');

// missing erasure request GET -> 404
const fakeReq = '00000000-0000-4000-8000-000000000000';
const missingReq = await api(`/v1/erasure-requests/${fakeReq}`, 'GET', undefined, 404);
console.log('missing erasure request -> 404 OK', JSON.stringify(missingReq.body));

// valid request + immediate completion + GET after completion returns completed
const key = `edge-key-${suffix}`;
const created = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 202, { 'idempotency-key': key });
console.log('created', JSON.stringify(created.body));

let final;
for (let i = 0; i < 40; i++) {
  const s = await api(`/v1/erasure-requests/${created.body.id}`);
  final = s.body;
  if (s.body.status === 'completed' || s.body.status === 'failed') break;
  await new Promise((r) => setTimeout(r, 250));
}
console.log('final', JSON.stringify(final));
if (final.status !== 'completed') throw new Error('expected completion');

// posting again after completion with a brand new key should still return same (already-completed) request
const postCompletionKey = `post-completion-${suffix}`;
const afterCompletion = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 202, { 'idempotency-key': postCompletionKey });
if (afterCompletion.body.id !== created.body.id) throw new Error('expected same request after completion');
if (afterCompletion.body.status !== 'completed') throw new Error('expected completed status on repeat request');
console.log('repeat request after completion returns completed OK', JSON.stringify(afterCompletion.body));

console.log('EDGE CASES PASSED');

