const gateway = 'http://localhost:3000';
const apiKey = 'pf_local_dev_northstar_4ad1539de977';

async function api(path, method = 'GET', body, expected, headers = {}) {
  const init = { method, headers: { authorization: `Bearer ${apiKey}`, ...headers } };
  if (body !== undefined) { init.headers['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const response = await fetch(`${gateway}${path}`, init);
  let payload;
  try { payload = await response.json(); } catch { payload = null; }
  if (expected !== undefined && response.status !== expected) {
    throw new Error(`${method} ${path}: expected ${expected}, got ${response.status}: ${JSON.stringify(payload)}`);
  }
  return { status: response.status, body: payload };
}

const suffix = Date.now();
const customer = await api('/v1/customers', 'POST', {
  externalReference: `retry-${suffix}`, email: `retry-${suffix}@example.test`, name: 'Retry Check Customer',
}, 201);
console.log('customer created', customer.body.id);

const key = `retry-key-${suffix}`;
const created = await api(`/v1/customers/${customer.body.id}/erasure-requests`, 'POST', undefined, 202, { 'idempotency-key': key });
console.log('created', JSON.stringify(created.body));

// wait a bit to observe failure due to opensearch being down
await new Promise((r) => setTimeout(r, 3000));
const failedState = await api(`/v1/erasure-requests/${created.body.id}`);
console.log('state while opensearch down', JSON.stringify(failedState.body));

console.log('DONE - now bring opensearch back up and re-check');

